import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) tajwīd: sakt, rawm and ishmām, the exceptions of Ḥafṣ, the pronoun hāʾ, madd interactions, iltiqāʾ al-sākinayn, idghām nāqiṣ, tafkhīm and tarqīq, ibtidāʾ. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "xtj-001", s: "tajweed", g: 4, d: 6, t: ["sakt", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī (al-Shāṭibiyya), bāb al-sakt; Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, bāb al-sakt",
    en: ["Which list gives the four places where Ḥafṣ ʿan ʿĀṣim (the transmission in the Shāṭibiyya) makes a sakta?", ["The tanwīn alif of ʿiwajā in 18:1, marqadinā in 36:52, man in 75:27 and bal in 83:14", "The word rayb in 2:2, marqadinā in 36:52, man in 75:27 and bal in 83:14", "The tanwīn alif of ʿiwajā in 18:1, marqadinā in 36:52, bal in 83:14 and the first word of 112:1", "The word ʿiwajā in 18:1, man in 75:27, bal in 83:14 and the last word of 114:6"], "Ḥafṣ pauses without breath at four places: after ʿiwajā (18:1), after marqadinā (36:52), after man (75:27) and after bal (83:14). These are the only obligatory sakatāt in his riwāya; the sakta is a feature that Ḥamza and others extend to many more places, such as before every hamza after a sākin letter. The Shāṭibiyya lists them in its chapter on sakt."],
    de: ["Welche Liste nennt die vier Stellen, an denen Ḥafṣ ʿan ʿĀṣim (die Überlieferung der Šāṭibiyya) eine Sakta macht?", ["Das Tanwīn-Alif von ʿiwaǧā in 18:1, marqadinā in 36:52, man in 75:27 und bal in 83:14", "Das Wort rayb in 2:2, marqadinā in 36:52, man in 75:27 und bal in 83:14", "Das Tanwīn-Alif von ʿiwaǧā in 18:1, marqadinā in 36:52, bal in 83:14 und das erste Wort von 112:1", "Das Wort ʿiwaǧā in 18:1, man in 75:27, bal in 83:14 und das letzte Wort von 114:6"], "Ḥafṣ hält an vier Stellen ohne Atmen inne: nach ʿiwaǧā (18:1), nach marqadinā (36:52), nach man (75:27) und nach bal (83:14). Das sind die einzigen verpflichtenden Sakatāt in seiner Riwāya; die Sakta, die Ḥamza und andere auf viele weitere Stellen ausdehnen, etwa vor jedem Hamza nach einem Sākin-Buchstaben. Die Šāṭibiyya führt sie in ihrem Kapitel über das Sakt auf."],
    ar: ["أي قائمة تذكر المواضع الأربعة التي يسكت فيها حفص عن عاصم (من طريق الشاطبية)؟", ["ألف التنوين في الكلمة الأخيرة من الكهف 1، والكلمة الأخيرة قبل اسم الإشارة في يس 52، والكلمة بعد واو الاستئناف في القيامة 27، والكلمة بعد حرف الإضراب في المطففين 14", "الكلمة الأولى من البقرة 2، والكلمة الأخيرة قبل اسم الإشارة في يس 52، والكلمة بعد واو الاستئناف في القيامة 27، والكلمة بعد حرف الإضراب في المطففين 14", "ألف التنوين في الكلمة الأخيرة من الكهف 1، والكلمة الأخيرة قبل اسم الإشارة في يس 52، والكلمة بعد حرف الإضراب في المطففين 14، وأول كلمة في الإخلاص 1", "الكلمة الأخيرة من الكهف 1، والكلمة بعد واو الاستئناف في القيامة 27، والكلمة بعد حرف الإضراب في المطففين 14، وآخر كلمة في الناس 6"], "يسكت حفص سكتة لطيفة بلا تنفس في أربعة مواضع: آخر الكهف 1، وقبل اسم الإشارة في يس 52، وبعد أداة الاستفهام في القيامة 27، وبعد حرف الإضراب في المطففين 14. وهذه هي السكتات الواجبة عنده، أما حمزة وغيره فيوسّعون السكت في مواضع كثيرة كالسكت قبل الهمز بعد الساكن. وقد جمعها الشاطبي في باب السكت."] },

  { id: "xtj-002", s: "tajweed", g: 4, d: 6, t: ["sakt", "hafs-exceptions"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, bāb al-sakt; Makkī ibn Abī Ṭālib, al-Kashf ʿan Wujūh al-Qirāʾāt", v: "18:1", w: 11,
    en: ["Why is the sakta placed after the highlighted word, according to the classical explanation?", ["To show that the word that follows (‘straight’) is not a description of ‘crookedness’ but a separate state of the Book", "To prevent the tanwīn from being turned into a nūn", "To mark the end of a verse in the reading of Ḥafṣ", "To allow the reader to take a breath before the hamza"], "The sakta separates the two words so that the listener does not take ‘straight’ as qualifying ‘crookedness’, which would be absurd. The Book is meant to be straight, and the word is a ḥāl of the Book. Without the sakta the connection of the tanwīn alif and the following word could suggest the wrong meaning. This reason is given in the books of qirāʾāt such as al-Nashr."],
    de: ["Warum steht nach dem markierten Wort die Sakta, nach der klassischen Erklärung?", ["Um zu zeigen, dass das folgende Wort (‚gerade‘) keine Beschreibung von ‚Krümmung‘ ist, sondern ein eigener Zustand des Buches", "Um zu verhindern, dass das Tanwīn in ein Nūn verwandelt wird", "Um das Ende eines Verses in der Lesart von Ḥafṣ zu kennzeichnen", "Um dem Leser vor dem Hamza einen Atemzug zu erlauben"], "Die Sakta trennt die beiden Wörter, damit der Hörer ‚gerade‘ nicht als Attribut von ‚Krümmung‘ versteht, was widersinnig wäre. Das Buch soll gerade sein, und das Wort ist ein Ḥāl des Buches. Ohne die Sakta könnte die Verbindung von Tanwīn-Alif und folgendem Wort den falschen Sinn nahelegen. Diese Begründung findet sich in den Büchern der Qirāʾāt wie al-Našr."],
    ar: ["لماذا تُوضع السكتة بعد الكلمة المظللة على التعليل المأثور عند القراء؟", ["لبيان أن الكلمة التالية (المستقيم) ليست صفة للعوج بل حال مستقلة للكتاب", "لمنع قلب التنوين نونًا", "لبيان نهاية آية في قراءة حفص", "لإتاحة التنفس قبل الهمزة"], "فصلت السكتة بين الكلمتين حتى لا يُظن أن الكلمة التالية وصف للعوج وهو محال، فالكتاب هو المستقيم والكلمة التالية حال منه. ولو وُصل الكلام لجاز أن يُتوهم الوصل بين الألف المنونة وما بعدها فيفسد المعنى. وهذا التعليل مذكور في كتب القراءات كالنشر."] },

  { id: "xtj-003", s: "tajweed", g: 4, d: 6, t: ["sakt", "hafs-exceptions"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, bāb al-sakt; al-Dānī, al-Taysīr", v: "36:52", w: 6,
    en: ["What is the purpose of the sakta on the highlighted word in the reading of Ḥafṣ?", ["To separate it from the next word, so that ‘this’ is not taken as a qualifier of ‘our resting place’", "To avoid the idghām of dāl into the following letter", "To lengthen the madd that precedes the hamza", "To mark a stop that is obligatory in all riwāyāt"], "The next word begins a new statement: it is the answer of the angels or believers after the sinners ask who woke them. The sakta stops the voice briefly so that ‘this’ is not read as describing the resting place. Other transmitters link the words and rely on the sense; Ḥafṣ makes the break explicit without a breath."],
    de: ["Was ist der Zweck der Sakta beim markierten Wort in der Lesart von Ḥafṣ?", ["Es vom nächsten Wort zu trennen, damit ‚dies‘ nicht als Attribut von ‚unserer Ruhestätte‘ verstanden wird", "Das Idġām des Dāl in den folgenden Buchstaben zu vermeiden", "Das Madd vor dem Hamza zu verlängern", "Einen Halt zu markieren, der in allen Riwāyāt verpflichtend ist"], "Das nächste Wort beginnt eine neue Aussage: Es ist die Antwort der Engel oder Gläubigen, nachdem die Sünder fragen, wer sie geweckt hat. Die Sakta unterbricht die Stimme kurz, damit ‚dies‘ nicht als Beschreibung der Ruhestätte gelesen wird. Andere Überlieferer verbinden die Wörter und verlassen sich auf den Sinn; Ḥafṣ macht den Einschnitt ohne Atem ausdrücklich."],
    ar: ["ما الغرض من السكتة على الكلمة المظللة في قراءة حفص؟", ["الفصل بينها وبين الكلمة التالية حتى لا يُظن أن اسم الإشارة وصف للمرقد", "منع إدغام الدال في الحرف بعدها", "تطويل المد قبل الهمزة", "الإشارة إلى وقف واجب في كل الروايات"], "ما بعد الكلمة جملة جديدة هي جواب الملائكة أو المؤمنين بعد سؤال الكفار عمّن بعثهم، فتقطع السكتة الصوت لحظة حتى لا يُظن أن اسم الإشارة وصف للمرقد، وغير حفص يصل ويعتمد على المعنى، أما حفص فيصرّح بالفصل بلا تنفس."] },

  { id: "xtj-004", s: "tajweed", g: 4, d: 7, t: ["sakt", "idgham"], src: "Ibn al-Jazarī, al-Nashr, bāb al-sakt; al-Shāṭibī, Ḥirz al-Amānī", v: "75:27", w: 2,
    en: ["In Ḥafṣ the sakta after the highlighted word has a second function beyond separating the two words. What does it prevent?", ["The idghām of the nūn into the rāʾ of the next word", "The ikhfāʾ of the nūn before a ḥalqī letter", "The qalb of the nūn into a mīm", "The ghunna of the nūn"], "A nūn sākina before a rāʾ is normally assimilated with idghām bi-ghayr ghunna, which would turn the two words into something like ‘marrāq’ and hide that ‘man’ is a separate question word (‘who is an enchanter?’). The sakta keeps the nūn distinct. The same reasoning applies to the lām in 83:14 and the rāʾ that follows it."],
    de: ["Bei Ḥafṣ hat die Sakta nach dem markierten Wort neben der Trennung der beiden Wörter eine zweite Funktion. Was verhindert sie?", ["Das Idġām des Nūn in das Rāʾ des nächsten Wortes", "Das Iḫfāʾ des Nūn vor einem Kehllaut", "Das Qalb des Nūn in ein Mīm", "Die Ġunna des Nūn"], "Ein Nūn sākina vor einem Rāʾ wird normalerweise ohne Ġunna assimiliert, was die zwei Wörter zu etwas wie ‚marrāq‘ verschmelzen und verbergen würde, dass ‚man‘ ein eigenständiges Fragewort ist (‚wer ist ein Beschwörer?‘). Die Sakta hält das Nūn getrennt. Dieselbe Überlegung gilt für das Lām in 83:14 und das darauffolgende Rāʾ."],
    ar: ["في قراءة حفص للسكتة بعد الكلمة المظللة وظيفة ثانية غير الفصل بين الكلمتين. ما الذي تمنعه؟", ["إدغام النون في الراء من الكلمة التالية", "إخفاء النون عند حرف حلقي", "قلب النون ميمًا", "الغنة في النون"], "النون الساكنة قبل الراء تُدغم عادةً بغير غنة فتختلط الكلمتان (فتلتبس الكلمتان بكلمة واحدة) ويغيب أن الكلمة الأولى استفهام مستقل، فتمنع السكتة الإدغام وتُبقي النون ظاهرة. والتعليل نفسه في اللام والراء من المطففين 14."] },

  { id: "xtj-005", s: "tajweed", g: 4, d: 7, t: ["sakt", "waqf"], src: "Ibn al-Jazarī, al-Nashr, bāb al-sakt; Ibn al-Jazarī, al-Tamhīd fī ʿIlm al-Tajwīd", v: "83:14", w: 2,
    en: ["Which statement correctly distinguishes the sakta at the highlighted word from a waqf and from a qaṭʿ?", ["The sakta is a brief stop of the voice without taking breath, shorter than a waqf, after which the reading continues at once", "The sakta is a stop with breath of about six ḥarakāt, followed by a new beginning", "The sakta is a prolongation of the lām for two ḥarakāt with continued voice", "The sakta is the same as a waqf, but only done at the end of a verse"], "In the terminology of the qurrāʾ, the sakt is a cutting of the sound for a short time (about two ḥarakāt, as is commonly said) without breathing; a waqf includes breathing and is longer, and a qaṭʿ ends the reading altogether. It is therefore also a different thing from a ‘pause sign’ in the muṣḥaf. That is why the sakta here does not allow the reader to take a breath."],
    de: ["Welche Aussage unterscheidet die Sakta beim markierten Wort richtig von einem Waqf und einem Qaṭʿ?", ["Die Sakta ist ein kurzes Anhalten der Stimme ohne Atemholen, kürzer als ein Waqf, danach geht die Lesung sofort weiter", "Die Sakta ist ein Halt mit Atemholen von etwa sechs Ḥarakāt, gefolgt von einem Neubeginn", "Die Sakta ist eine Dehnung des Lām für zwei Ḥarakāt bei fortlaufender Stimme", "Die Sakta ist dasselbe wie ein Waqf, aber nur am Versende"], "In der Terminologie der Qurrāʾ ist das Sakt ein Abbrechen des Klangs für kurze Zeit (gewöhnlich etwa zwei Ḥarakāt) ohne Atemholen; ein Waqf schließt das Atmen ein und ist länger, und ein Qaṭʿ beendet die Lesung ganz. Es ist also auch etwas anderes als ein ‚Pausenzeichen‘ im Muṣḥaf. Deshalb erlaubt die Sakta hier kein Atemholen."],
    ar: ["أي عبارة تفرّق على الوجه الصحيح بين السكتة على الكلمة المظللة والوقف والقطع؟", ["السكتة قطع الصوت زمنًا يسيرًا بلا تنفس وهي أقصر من الوقف ثم يستمر القارئ فورًا", "السكتة وقف مع تنفس بمقدار ست حركات يعقبه ابتداء جديد", "السكتة مدّ للام بمقدار حركتين مع استمرار الصوت", "السكتة هي الوقف نفسه ولكن عند آخر الآية فقط"], "السكت عند القراء قطع الصوت زمنًا قليلًا (نحو حركتين على المشهور) دون تنفس، أما الوقف فمعه تنفس وزمنه أطول، والقطع إنهاء للقراءة. وهو غير علامة الوقف في المصحف، ولذلك لا يجوز التنفس عند السكتة هنا."] },

  { id: "xtj-006", s: "tajweed", g: 4, d: 6, t: ["rawm-ishmam", "waqf"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, bāb al-waqf; al-Dānī, al-Taysīr",
    en: ["Which statement correctly distinguishes rawm from ishmām at waqf on a final letter?", ["Rawm pronounces part of the vowel so that a near listener hears it; ishmām is a rounding of the lips for ḍamma after the sukūn, heard by no one", "Rawm is a rounding of the lips and ishmām is a whisper of the vowel", "Both are heard by the listener but ishmām is longer", "Rawm is for sukūn and ishmām is for the tanwīn"], "Rawm is the pronunciation of a part (traditionally a third) of the vowel in a low voice, so that it is audible to someone close by. Ishmām is only a visible gesture of the lips for ḍamma after the letter has been made sākin, with no sound, so a blind person cannot perceive it. The classical books give these definitions in the chapter on waqf."],
    de: ["Welche Aussage unterscheidet Rawm und Ishmām beim Waqf auf einem Endbuchstaben richtig?", ["Rawm spricht einen Teil des Vokals aus, sodass ein Nahestehender ihn hört; Ishmām ist ein Runden der Lippen für Ḍamma nach dem Sukūn und wird von niemandem gehört", "Rawm ist ein Runden der Lippen, Ishmām ein Flüstern des Vokals", "Beide werden vom Hörer wahrgenommen, aber Ishmām ist länger", "Rawm gilt für Sukūn und Ishmām für das Tanwīn"], "Rawm ist die Aussprache eines Teils (überlieferungsgemäß eines Drittels) des Vokals mit leiser Stimme, sodass er für jemanden in der Nähe hörbar ist. Ishmām ist nur eine sichtbare Lippengeste für Ḍamma, nachdem der Buchstabe sākin gemacht wurde, ohne Klang, sodass ein Blinder sie nicht wahrnehmen kann. Die klassischen Bücher geben diese Definitionen im Kapitel über den Waqf."],
    ar: ["أي عبارة تفرّق على الوجه الصحيح بين الروم والإشمام عند الوقف على الحرف الأخير؟", ["الروم نطق ببعض الحركة بصوت خفي يسمعه القريب، والإشمام ضمّ الشفتين للضمة بعد التسكين دون صوت", "الروم ضمّ الشفتين والإشمام همس بالحركة", "كلاهما يسمعه المستمع لكن الإشمام أطول", "الروم للسكون والإشمام للتنوين"], "الروم الإتيان ببعض الحركة (ثلثها في التعريف المأثور) بصوت خفي يسمعه من قرب، والإشمام إشارة بالشفتين إلى الضمة بعد تسكين الحرف دون صوت فلا يدركه الأعمى. وهذه التعريفات في باب الوقف من كتب القراءات."] },

  { id: "xtj-007", s: "tajweed", g: 4, d: 6, t: ["rawm-ishmam", "waqf"], src: "Ibn al-Jazarī, al-Nashr, bāb al-waqf ʿalā ākhir al-kalima",
    en: ["On which vowels is rawm permitted at waqf, and on which is ishmām?", ["Rawm on ḍamma and kasra; ishmām only on ḍamma", "Rawm on fatḥa and ḍamma; ishmām on kasra", "Rawm on all three vowels; ishmām on ḍamma only", "Rawm only on kasra; ishmām on all three vowels"], "Rawm can be done on ḍamma and kasra, because these vowels can be partly pronounced; fatḥa is too light and is excluded by most. Ishmām is possible only for ḍamma, because the lips are rounded to show it, and fatḥa and kasra have no corresponding lip gesture."],
    de: ["Bei welchen Vokalen ist Rawm beim Waqf erlaubt, und bei welchen Ishmām?", ["Rawm bei Ḍamma und Kasra; Ishmām nur bei Ḍamma", "Rawm bei Fatḥa und Ḍamma; Ishmām bei Kasra", "Rawm bei allen drei Vokalen; Ishmām nur bei Ḍamma", "Rawm nur bei Kasra; Ishmām bei allen drei Vokalen"], "Rawm kann bei Ḍamma und Kasra geschehen (und nicht beim Tanwīn selbst), da diese Vokale teilweise ausgesprochen werden können; Fatḥa ist zu leicht und wird von den meisten ausgeschlossen. Ishmām ist nur bei Ḍamma möglich, weil man die Lippen dafür rundet, und Fatḥa und Kasra haben keine entsprechende Lippengeste."],
    ar: ["على أي حركات يجوز الروم عند الوقف وعلى أيها الإشمام؟", ["الروم في الضمة والكسرة والإشمام في الضمة فقط", "الروم في الفتحة والضمة والإشمام في الكسرة", "الروم في الحركات الثلاث والإشمام في الضمة فقط", "الروم في الكسرة فقط والإشمام في الحركات الثلاث"], "يجوز الروم في الضمة والكسرة لأنهما تقبلان النطق ببعضهما، وتُستثنى الفتحة عند أكثر القراء لخفتها، أما الإشمام فللضمة وحدها لأنه ضمّ للشفتين، وليس للفتحة والكسرة إشارة شفوية تقابلهما."] },

  { id: "xtj-008", s: "tajweed", g: 4, d: 7, t: ["rawm-ishmam", "waqf"], src: "Ibn al-Jazarī, al-Nashr, bāb al-waqf ʿalā ākhir al-kalima; al-Dānī, al-Taysīr", v: "1:5", w: 2,
    en: ["If a reader stops on the highlighted word, which of these statements is correct?", ["Rawm or ishmām is allowed, because the last letter carries an original ḍamma", "Neither is allowed, because the word has no tanwīn", "Only rawm is allowed, because the verb is imperfect", "Only ishmām is allowed, because the word is a verb"], "The final dāl has an original ḍamma that is dropped at waqf, so both rawm and ishmām are permitted. Neither is allowed for fatḥa, for the hāʾ of feminine nouns that is changed from tāʾ, for the mīm of the plural, or for a vowel that is only temporary. A verb does not change the rule."],
    de: ["Wenn ein Leser auf dem markierten Wort stoppt, welche Aussage ist richtig?", ["Rawm oder Ishmām sind erlaubt, da der letzte Buchstabe eine ursprüngliche Ḍamma trägt", "Keines von beiden ist erlaubt, da das Wort kein Tanwīn hat", "Nur Rawm ist erlaubt, da das Verb ein Imperfekt ist", "Nur Ishmām ist erlaubt, da das Wort ein Verb ist"], "Das letzte Dāl hat eine ursprüngliche Ḍamma, die beim Waqf wegfällt, daher sind Rawm und Ishmām beide erlaubt. Keines von beiden ist erlaubt bei Fatḥa, bei dem Hāʾ femininer Nomen, das aus Tāʾ entstand, beim Mīm des Plurals oder bei einem nur vorübergehenden Vokal. Ein Verb ändert die Regel nicht."],
    ar: ["إذا وقف القارئ على الكلمة المظللة فأي عبارة صحيحة؟", ["يجوز الروم والإشمام لأن الحرف الأخير عليه ضمة أصلية", "لا يجوز شيء منهما لأن الكلمة بلا تنوين", "يجوز الروم فقط لأن الفعل مضارع", "يجوز الإشمام فقط لأن الكلمة فعل"], "على الدال ضمة أصلية تسقط في الوقف فيجوز فيها الروم والإشمام، ولا يجوز في المفتوح ولا في هاء التأنيث المبدلة من التاء ولا في ميم الجمع ولا في الحركة العارضة. وكون الكلمة فعلًا لا يغيّر الحكم."] },

  { id: "xtj-009", s: "tajweed", g: 4, d: 7, t: ["rawm-ishmam", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb ishmām al-sīn; Ibn al-Jazarī, al-Nashr, bāb al-idghām", v: "12:11", w: 6,
    en: ["How does Ḥafṣ read the highlighted word, in which a nūn sākina and a following nūn meet?", ["Idghām of the first nūn into the second, together with ishmām (a rounding of the lips for ḍamma before the idghām)", "Complete iẓhār of both nūns with ghunna", "Plain ikhfāʾ without any sign of the vowel", "Ishmām with a full audible ḍamma and no idghām"], "The word is written with a single nūn plus a mark; its original form had two nūns, the first with ḍamma. Ḥafṣ gives the first nūn an ishmām (the lips round for the ḍamma) and then assimilates it, so that the vowel is hinted but not sounded. Some transmitters read plain ikhfāʾ or iẓhār; Abū Jaʿfar reads a complete idghām without the lip gesture."],
    de: ["Wie liest Ḥafṣ das markierte Wort, in dem ein Nūn sākina und ein folgendes Nūn zusammentreffen?", ["Idġām des ersten Nūn in das zweite, zusammen mit Ishmām (Lippenrundung für Ḍamma vor dem Idġām)", "Vollständiges Iẓhār beider Nūn mit Ġunna", "Schlichtes Iḫfāʾ ohne jedes Zeichen des Vokals", "Ishmām mit voll hörbarer Ḍamma und ohne Idġām"], "Das Wort ist mit einem einzigen Nūn plus Zeichen geschrieben; seine ursprüngliche Form hatte zwei Nūn, das erste mit Ḍamma. Ḥafṣ gibt dem ersten Nūn ein Ishmām (die Lippen runden sich für die Ḍamma) und assimiliert es dann, sodass der Vokal angedeutet, aber nicht gesprochen wird. Manche Überlieferer lesen schlichtes Iḫfāʾ oder Iẓhār; Abū Jaʿfar liest ein vollständiges Idġām ohne Lippengeste."],
    ar: ["كيف يقرأ حفص الكلمة المظللة التي تجتمع فيها نون ساكنة ونون بعدها؟", ["بإدغام النون الأولى في الثانية مع الإشمام (ضمّ الشفتين للضمة قبل الإدغام)", "بإظهار النونين مع الغنة تامًّا", "بإخفاء مجرد دون أي إشارة إلى الحركة", "بإشمام مع ضمة مسموعة كاملة دون إدغام"], "الكلمة مكتوبة بنون واحدة مع علامة، وأصلها نونان الأولى مضمومة، فيجمع حفص بين الإدغام والإشمام: يضمّ الشفتين للضمة ثم يدغم فلا يسمع من الحركة إلا إشارتها. وقرأ بعض القراء بالإخفاء أو الإظهار وأبو جعفر بالإدغام المحض بلا إشارة."] },

  { id: "xtj-010", s: "tajweed", g: 4, d: 6, t: ["ha-kinaya", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb hāʾ al-kināya; Ibn al-Jazarī, al-Nashr, bāb hāʾ al-kināya", v: "25:69", w: 7,
    en: ["The rule is that the pronoun hāʾ has no silā (lengthening) after a sākin letter. What does Ḥafṣ do at the highlighted word, which breaks the rule?", ["He gives the hāʾ a silā of two ḥarakāt, although it follows the sākin yāʾ", "He drops the silā and reads the hāʾ with sukūn", "He reads the hāʾ with ḍamma and no silā", "He reads a silā of six ḥarakāt"], "The general rule for Ḥafṣ is that a pronoun hāʾ between two vowelled letters gets silā, and one after a sākin letter does not. In this word he makes an exception and reads a silā ṣughrā (two ḥarakāt) after the sākin yāʾ, a unique case in his riwāya. The Shāṭibiyya treats it as a deliberate exception."],
    de: ["Die Regel lautet, dass das Pronomen Hāʾ nach einem Sākin-Buchstaben keine Ṣila (Dehnung) hat. Was tut Ḥafṣ beim markierten Wort, das die Regel durchbricht?", ["Er gibt dem Hāʾ eine Ṣila von zwei Ḥarakāt, obwohl es auf das Sākin-Yāʾ folgt", "Er lässt die Ṣila weg und liest das Hāʾ mit Sukūn", "Er liest das Hāʾ mit Ḍamma und ohne Ṣila", "Er liest eine Ṣila von sechs Ḥarakāt"], "Die allgemeine Regel bei Ḥafṣ lautet, dass ein Pronomen-Hāʾ zwischen zwei vokalisierten Buchstaben eine Ṣila erhält und nach einem Sākin-Buchstaben keine. Bei diesem Wort macht er eine Ausnahme und liest eine Ṣila ṣuġrā (zwei Ḥarakāt) nach dem Sākin-Yāʾ, ein einzigartiger Fall in seiner Riwāya. Die Šāṭibiyya behandelt es als bewusste Ausnahme."],
    ar: ["القاعدة أن هاء الضمير لا تُوصل بعد حرف ساكن. فماذا يفعل حفص في الكلمة المظللة مخالفةً للقاعدة؟", ["يصل الهاء بمد قدره حركتان مع أنها بعد ياء ساكنة", "يحذف الصلة ويسكّن الهاء", "يقرأ الهاء بالضم بلا صلة", "يمدّها ست حركات"], "الأصل عند حفص أن هاء الضمير الواقعة بين متحركين توصل وأن الواقعة بعد ساكن لا توصل. وفي هذه الكلمة خالف الأصل فوصل الهاء بعد الياء الساكنة بمقدار حركتين، وهذا موضع منفرد في روايته، وقد نبّهت الشاطبية عليه استثناءً."] },

  { id: "xtj-011", s: "tajweed", g: 4, d: 6, t: ["ha-kinaya", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb hāʾ al-kināya; Ibn al-Jazarī, al-Nashr", v: "39:7", w: 13,
    en: ["The highlighted pronoun hāʾ stands between two vowelled letters. What is the reading of Ḥafṣ?", ["Ḍamma on the hāʾ without silā", "Ḍamma on the hāʾ with a silā of two ḥarakāt", "Sukūn on the hāʾ", "Kasra on the hāʾ with silā"], "By the general rule a pronoun hāʾ between two vowelled letters takes silā. Here Ḥafṣ reads the ḍamma without the silā (the hāʾ is short), another exception noted by the books on the hāʾ al-kināya. Other transmitters read it with silā, and others with sukūn."],
    de: ["Das markierte Pronomen-Hāʾ steht zwischen zwei vokalisierten Buchstaben. Wie liest es Ḥafṣ?", ["Ḍamma auf dem Hāʾ ohne Ṣila", "Ḍamma auf dem Hāʾ mit einer Ṣila von zwei Ḥarakāt", "Sukūn auf dem Hāʾ", "Kasra auf dem Hāʾ mit Ṣila"], "Nach der allgemeinen Regel erhält ein Pronomen-Hāʾ zwischen zwei vokalisierten Buchstaben eine Ṣila. Hier liest Ḥafṣ die Ḍamma ohne Ṣila (das Hāʾ ist kurz), eine weitere Ausnahme, die die Bücher über das Hāʾ al-kināya vermerken. Andere Überlieferer lesen sie mit Ṣila, wieder andere mit Sukūn."],
    ar: ["هاء الضمير المظللة بين متحركين. ما قراءة حفص فيها؟", ["بضم الهاء بلا صلة", "بضم الهاء مع صلة بمقدار حركتين", "بإسكان الهاء", "بكسر الهاء مع صلة"], "الأصل أن هاء الضمير بين متحركين توصل، لكن حفصًا يقرأ هنا بالضم دون صلة (قصر)، وهو من المواضع المستثناة في باب هاء الكناية، ويصلها بعض القراء وأسكنها آخرون."] },

  { id: "xtj-012", s: "tajweed", g: 4, d: 7, t: ["ha-kinaya", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb hāʾ al-kināya; Ibn al-Jazarī, al-Nashr", v: "24:52", w: 7,
    en: ["How does Ḥafṣ read the highlighted word?", ["With sukūn on the qāf and kasra on the hāʾ, without silā", "With kasra on the qāf and a silā on the hāʾ", "With sukūn on both the qāf and the hāʾ", "With fatḥa on the qāf and ḍamma on the hāʾ"], "Ḥafṣ silences the qāf and gives the hāʾ a kasra without silā, so the word is shortened. Other transmitters read the qāf with kasra and give the hāʾ a silā, or use other vocalisations. This word is a standard example in the chapter on the pronoun hāʾ."],
    de: ["Wie liest Ḥafṣ das markierte Wort?", ["Mit Sukūn auf dem Qāf und Kasra auf dem Hāʾ, ohne Ṣila", "Mit Kasra auf dem Qāf und einer Ṣila auf dem Hāʾ", "Mit Sukūn auf Qāf und Hāʾ", "Mit Fatḥa auf dem Qāf und Ḍamma auf dem Hāʾ"], "Ḥafṣ macht das Qāf stumm und gibt dem Hāʾ eine Kasra ohne Ṣila, sodass das Wort verkürzt wird. Andere Überlieferer lesen das Qāf mit Kasra und geben dem Hāʾ eine Ṣila oder verwenden andere Vokalisierungen. Dieses Wort ist ein Standardbeispiel im Kapitel über das Pronomen-Hāʾ."],
    ar: ["كيف يقرأ حفص الكلمة المظللة؟", ["بإسكان القاف وكسر الهاء بلا صلة", "بكسر القاف ووصل الهاء", "بإسكان القاف والهاء معًا", "بفتح القاف وضم الهاء"], "يخفف حفص الكلمة بإسكان القاف وكسر الهاء من غير صلة، وقرأ غيره بكسر القاف ووصل الهاء أو بوجوه أخرى، والكلمة من أمثلة باب هاء الكناية."] },

  { id: "xtj-013", s: "tajweed", g: 4, d: 6, t: ["ha-kinaya", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb hāʾ al-kināya; al-Dānī, al-Taysīr", v: "7:111", w: 2,
    en: ["How does Ḥafṣ read the hāʾ of the highlighted imperative (the same word occurs in 26:36)?", ["With sukūn on the hāʾ", "With ḍamma and silā", "With kasra and silā", "With kasra and no silā"], "Ḥafṣ reads the hāʾ sākina, whereas other transmitters read it with a vowel, with silā, or with a hamza. The word is a notable example of the rule that pronoun hāʾ may be read with sukūn for lightness, and it must be learned as an exception."],
    de: ["Wie liest Ḥafṣ das Hāʾ des markierten Imperativs (dasselbe Wort steht in 26:36)?", ["Mit Sukūn auf dem Hāʾ", "Mit Ḍamma und Ṣila", "Mit Kasra und Ṣila", "Mit Kasra und ohne Ṣila"], "Ḥafṣ liest das Hāʾ sākina, während andere Überlieferer es mit Vokal, mit Ṣila oder mit Hamza lesen. Das Wort ist ein bekanntes Beispiel dafür, dass das Pronomen-Hāʾ zur Erleichterung mit Sukūn gelesen werden kann, und es muss als Ausnahme gelernt werden."],
    ar: ["كيف يقرأ حفص هاء الأمر المظلل (والكلمة نفسها في الشعراء 36)؟", ["بإسكان الهاء", "بضم الهاء مع صلة", "بكسر الهاء مع صلة", "بكسر الهاء بلا صلة"], "يقرأ حفص الهاء ساكنة، بينما يقرؤها غيره بحركة أو بصلة أو بالهمز. والكلمة مثال على جواز إسكان هاء الضمير للتخفيف، ولا بد من حفظها استثناءً."] },

  { id: "xtj-014", s: "tajweed", g: 4, d: 6, t: ["ha-kinaya", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb hāʾ al-kināya; Ibn al-Jazarī, al-Nashr", v: "27:28", w: 4,
    en: ["The highlighted verb ends in the pronoun hāʾ. Which of these statements about Ḥafṣ is correct?", ["The hāʾ is read with sukūn, as in the verb of 7:111", "The hāʾ takes kasra and a silā because it follows a kasra", "The hāʾ takes ḍamma without silā", "The hāʾ takes fatḥa"], "By the general rule a pronoun hāʾ after a vowelled letter takes silā, but Ḥafṣ reads the sukūn, as in 7:111 and 26:36. Other transmitters read a vowel or a silā. Readers must therefore learn the three verbs together."],
    de: ["Das markierte Verb endet auf das Pronomen Hāʾ. Welche Aussage über Ḥafṣ ist richtig?", ["Das Hāʾ wird mit Sukūn gelesen, wie beim Verb in 7:111", "Das Hāʾ erhält Kasra und eine Ṣila, weil es nach Kasra folgt", "Das Hāʾ erhält Ḍamma ohne Ṣila", "Das Hāʾ erhält Fatḥa"], "Nach der allgemeinen Regel erhält ein Pronomen-Hāʾ nach einem vokalisierten Buchstaben eine Ṣila, doch Ḥafṣ liest das Sukūn, wie in 7:111 und 26:36. Andere Überlieferer lesen einen Vokal oder eine Ṣila. Die Leser müssen daher die drei Verben zusammen lernen."],
    ar: ["الفعل المظلل ينتهي بهاء الضمير. أي عبارة عن حفص صحيحة؟", ["الهاء تُقرأ ساكنة كما في فعل الأعراف 111", "الهاء مكسورة وتوصل لأنها بعد كسرة", "الهاء مضمومة بلا صلة", "الهاء مفتوحة"], "الأصل أن هاء الضمير بعد متحرك توصل، لكن حفصًا يسكّنها هنا كما في الأعراف 111 والشعراء 36، وغيره يحرّكها أو يصلها، فيحسن حفظ المواضع الثلاثة معًا."] },

  { id: "xtj-015", s: "tajweed", g: 4, d: 6, t: ["ha-kinaya", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb hāʾ al-kināya; Ibn al-Jazarī, al-Nashr", v: "48:10", w: 21,
    en: ["The pronoun hāʾ of the highlighted word follows a yāʾ. What does Ḥafṣ read?", ["Ḍamma on the hāʾ, the original vowel, instead of the usual kasra", "Kasra on the hāʾ, as the pronoun usually takes after yāʾ", "Sukūn on the hāʾ", "Fatḥa on the hāʾ"], "The general rule is that a hāʾ after yāʾ or kasra takes a kasra. Ḥafṣ keeps the original ḍamma of the pronoun in this word (and in 18:63), where others change it to a kasra. The result also affects the next word: the lām of the name of God, following a ḍamma, is read heavy."],
    de: ["Das Pronomen-Hāʾ des markierten Wortes folgt auf ein Yāʾ. Was liest Ḥafṣ?", ["Ḍamma auf dem Hāʾ, den ursprünglichen Vokal, statt der üblichen Kasra", "Kasra auf dem Hāʾ, wie das Pronomen sie nach Yāʾ gewöhnlich erhält", "Sukūn auf dem Hāʾ", "Fatḥa auf dem Hāʾ"], "Die allgemeine Regel lautet, dass ein Hāʾ nach Yāʾ oder Kasra eine Kasra erhält. Ḥafṣ behält in diesem Wort (und in 18:63) die ursprüngliche Ḍamma des Pronomens, wo andere sie zur Kasra ändern. Das Ergebnis wirkt sich auch auf das nächste Wort aus: Das Lām des Gottesnamens wird nach einer Ḍamma schwer gelesen."],
    ar: ["هاء الضمير في الكلمة المظللة بعد ياء. ماذا يقرأ حفص؟", ["بضم الهاء على الأصل بدل الكسر المعتاد", "بكسر الهاء كما هو المعتاد بعد الياء", "بإسكان الهاء", "بفتح الهاء"], "الأصل أن تُكسر الهاء بعد الياء أو الكسرة، لكن حفصًا يُبقي ضمة الضمير الأصلية في هذه الكلمة وفي الكهف 63 بينما يكسرها غيره. ويتأثر بذلك ما بعدها فاللام في لفظ الجلالة تُفخّم بعد الضمة."] },

  { id: "xtj-016", s: "tajweed", g: 4, d: 7, t: ["lam-jalala", "hafs-exceptions"], src: "Ibn al-Jazarī, al-Nashr, bāb al-lāmāt; Ibn al-Jazarī, al-Muqaddima al-Jazariyya", v: "48:10", w: 22,
    en: ["In the reading of Ḥafṣ, how is the lām of the highlighted name of God pronounced when read continuously from the previous word (which ends in hāʾ with ḍamma)?", ["Heavy (tafkhīm), because it follows a ḍamma", "Light (tarqīq), because the hāʾ is a soft letter", "Light, because the previous word contains a yāʾ", "Heavy only if one stops on the previous word"], "The lām of Allāh is heavy after fatḥa or ḍamma and light after kasra. Because Ḥafṣ reads the hāʾ of the previous word with ḍamma, the lām is heavy. A reader who read the previous hāʾ with kasra, as most transmitters do, would make the lām light. This is why such questions link the hāʾ rule to the rules of the lām."],
    de: ["Wie wird bei Ḥafṣ das Lām des markierten Gottesnamens ausgesprochen, wenn man vom vorigen Wort (das auf Hāʾ mit Ḍamma endet) fortlaufend liest?", ["Schwer (Tafḫīm), weil es auf eine Ḍamma folgt", "Leicht (Tarqīq), weil das Hāʾ ein weicher Buchstabe ist", "Leicht, weil das vorige Wort ein Yāʾ enthält", "Schwer nur, wenn man auf dem vorigen Wort stoppt"], "Das Lām von Allāh ist nach Fatḥa oder Ḍamma schwer und nach Kasra leicht. Da Ḥafṣ das Hāʾ des vorigen Wortes mit Ḍamma liest, ist das Lām schwer. Ein Leser, der das vorige Hāʾ wie die meisten Überlieferer mit Kasra läse, würde das Lām leicht sprechen. Deshalb verbinden solche Fragen die Hāʾ-Regel mit den Regeln des Lām."],
    ar: ["في قراءة حفص، كيف يُنطق اللام في لفظ الجلالة المظلل عند الوصل بالكلمة السابقة التي تنتهي بهاء مضمومة؟", ["مفخّمة لأنها بعد ضمة", "مرققة لأن الهاء حرف رقيق", "مرققة لأن الكلمة السابقة فيها ياء", "مفخّمة فقط إذا وقف على الكلمة السابقة"], "تُفخّم لام لفظ الجلالة بعد الفتح والضم وتُرقّق بعد الكسر. ولما كان حفص يقرأ هاء الكلمة السابقة بالضم فاللام مفخّمة، ولو قُرئت الهاء بالكسر كما عند أكثر الرواة لرُقّقت اللام، ولذلك يُربط حكم الهاء بحكم اللام."] },

  { id: "xtj-017", s: "tajweed", g: 4, d: 6, t: ["ha-kinaya", "hafs-exceptions"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb hāʾ al-kināya; Ibn al-Jazarī, al-Nashr", v: "18:63", w: 11,
    en: ["What is unusual about the highlighted word in the reading of Ḥafṣ?", ["The hāʾ keeps its original ḍamma although it follows a kasra and yāʾ", "The word has a silā of six ḥarakāt", "The word is read with imāla", "The word is read with tashīl of its hamza"], "The pronoun hāʾ of this word follows a yāʾ, and the rule would give it a kasra. Ḥafṣ keeps the ḍamma, as in 48:10, because this is how his transmission is established. This is one of the very few places where the vowel of a pronoun hāʾ against the usual rule is a matter of transmission."],
    de: ["Was ist beim markierten Wort in der Lesart von Ḥafṣ ungewöhnlich?", ["Das Hāʾ behält seine ursprüngliche Ḍamma, obwohl es auf Kasra und Yāʾ folgt", "Das Wort hat eine Ṣila von sechs Ḥarakāt", "Das Wort wird mit Imāla gelesen", "Das Wort wird mit Tashīl seines Hamza gelesen"], "Das Pronomen-Hāʾ dieses Wortes folgt auf ein Yāʾ, und die Regel würde ihm eine Kasra geben. Ḥafṣ behält die Ḍamma, wie in 48:10, weil so seine Überlieferung feststeht. Es ist eine der ganz wenigen Stellen, an denen der Vokal eines Pronomen-Hāʾ gegen die übliche Regel eine Frage der Überlieferung ist."],
    ar: ["ما الغريب في الكلمة المظللة في قراءة حفص؟", ["بقاء ضمة الهاء على الأصل مع أنها بعد ياء وكسرة", "فيها صلة بمقدار ست حركات", "تُقرأ بالإمالة", "يُسهَّل همزها"], "الأصل أن تُكسر هاء الضمير بعد الياء، لكن حفصًا يُبقي ضمتها هنا كما في الفتح 10 لأن روايته ثبتت هكذا، وهي من القليل الذي خالف فيه ضم الهاء القاعدة وكان الأمر فيه للنقل."] },

  { id: "xtj-018", s: "tajweed", g: 4, d: 6, t: ["hafs-exceptions", "hamza"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb al-hamzatayn min kalima; Ibn al-Jazarī, al-Nashr", v: "41:44", w: 9,
    en: ["How does Ḥafṣ read the double hamza of the highlighted word?", ["The second hamza is made easy (tashīl, between hamza and alif) without a lengthening alif between the two", "Both hamzas are pronounced fully with an intervening alif", "The second hamza is replaced by a full alif", "The first hamza is dropped"], "In this word Ḥafṣ is exceptional: he reads tashīl of the second hamza without ādkhāl (the alif of separation), whereas other riwāyāt either read both hamzas (taḥqīq) or insert an alif. The muṣḥaf shows it with a small sign. It is the only place in his riwāya where two hamzas of one word are treated like this."],
    de: ["Wie liest Ḥafṣ das doppelte Hamza des markierten Wortes?", ["Das zweite Hamza wird erleichtert (Tashīl, zwischen Hamza und Alif), ohne ein trennendes Dehnungs-Alif dazwischen", "Beide Hamza werden voll gesprochen, mit einem Alif dazwischen", "Das zweite Hamza wird durch ein volles Alif ersetzt", "Das erste Hamza fällt weg"], "Bei diesem Wort ist Ḥafṣ ein Sonderfall: Er liest Tashīl des zweiten Hamza ohne Ādḫāl (das trennende Alif), während andere Riwāyāt entweder beide Hamza sprechen (Taḥqīq) oder ein Alif einfügen. Der Muṣḥaf zeigt es mit einem kleinen Zeichen. Es ist der einzige Ort in seiner Riwāya, an dem zwei Hamza eines Wortes so behandelt werden."],
    ar: ["كيف يقرأ حفص الهمزتين في الكلمة المظللة؟", ["يسهّل الهمزة الثانية بين الهمزة والألف دون إدخال ألف بينهما", "يحقق الهمزتين ويدخل ألفًا بينهما", "يبدل الثانية ألفًا خالصة", "يحذف الهمزة الأولى"], "في هذا الموضع انفرد حفص بتسهيل الهمزة الثانية بلا إدخال، بينما حقق غيره الهمزتين أو أدخل ألفًا بينهما. ويُشار إليه في المصحف بعلامة صغيرة، وهو الموضع الوحيد في روايته الذي يُعامل فيه همزتان في كلمة هكذا."] },

  { id: "xtj-019", s: "tajweed", g: 4, d: 7, t: ["hafs-exceptions", "imala"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb al-fatḥ wa-l-imāla; Ibn al-Jazarī, al-Nashr, bāb al-imāla", v: "11:41", w: 6,
    en: ["What is special about the highlighted word in the riwāya of Ḥafṣ ʿan ʿĀṣim?", ["It is the only word where Ḥafṣ makes imāla (inclining the fatḥa and the alif toward kasra and yāʾ)", "It is the only word where he reads madd of 6 ḥarakāt", "It is the only word where he reads a sakta", "It is the only word where he reads ishmām"], "In the riwāya of Ḥafṣ there is no imāla in the whole Quran except in this word, in the form of an imāla kubrā in the rāʾ and the alif after it. The muṣḥaf shows the imāla with a special mark below the rāʾ. Other readers (Ḥamza, al-Kisāʾī, Khalaf) make imāla in many more words."],
    de: ["Was ist beim markierten Wort in der Riwāya von Ḥafṣ ʿan ʿĀṣim besonders?", ["Es ist das einzige Wort, bei dem Ḥafṣ Imāla macht (Neigung von Fatḥa und Alif zu Kasra und Yāʾ hin)", "Es ist das einzige Wort, in dem er ein Madd von 6 Ḥarakāt liest", "Es ist das einzige Wort, in dem er eine Sakta liest", "Es ist das einzige Wort, in dem er Ishmām liest"], "In der Riwāya von Ḥafṣ gibt es im ganzen Koran keine Imāla außer in diesem Wort, und zwar als Imāla kubrā beim Rāʾ und dem Alif danach. Der Muṣḥaf zeigt die Imāla mit einem besonderen Zeichen unter dem Rāʾ. Andere Leser (Ḥamza, al-Kisāʾī, Ḫalaf) machen Imāla in viel mehr Wörtern."],
    ar: ["ما الذي تختص به الكلمة المظللة في رواية حفص عن عاصم؟", ["هي الموضع الوحيد الذي يميل فيه حفص (يميل الفتحة والألف نحو الكسرة والياء)", "هي الموضع الوحيد الذي يمدّ فيه ست حركات", "هي الموضع الوحيد الذي يسكت فيه", "هي الموضع الوحيد الذي يشمّ فيه"], "ليس في رواية حفص إمالة في القرآن كله إلا في هذه الكلمة، وهي إمالة كبرى في الراء والألف بعدها، ويُشار إليها في المصحف بعلامة خاصة تحت الراء. أما حمزة والكسائي وخلف فيميلون في مواضع كثيرة."] },

  { id: "xtj-020", s: "tajweed", g: 4, d: 6, t: ["idgham", "idhhar-mutlaq"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, bāb al-nūn al-sākina; al-Shāṭibī, Ḥirz al-Amānī", v: "61:4", w: 10,
    en: ["The highlighted word contains a nūn sākina followed by yāʾ in the same word. How is it read?", ["With iẓhār muṭlaq (full clear pronunciation), because both letters are in one word", "With idghām bi-ghunna, as for the nūn before yāʾ", "With ikhfāʾ", "With qalb"], "The nūn before yāʾ, wāw, nūn or mīm is normally merged with ghunna, but not when nūn and yāʾ or wāw are in the same word: then the nūn is clearly pronounced so that the word does not become something else (‘buyyān’). Only four words are like this (dunyā, ṣinwān, qinwān, bunyān). The rule is called iẓhār muṭlaq."],
    de: ["Das markierte Wort enthält ein Nūn sākina, gefolgt von Yāʾ im selben Wort. Wie wird es gelesen?", ["Mit Iẓhār muṭlaq (volle, deutliche Aussprache), weil beide Buchstaben in einem Wort stehen", "Mit Idġām bi-ġunna, wie beim Nūn vor Yāʾ", "Mit Iḫfāʾ", "Mit Qalb"], "Das Nūn vor Yāʾ, Wāw, Nūn oder Mīm wird normalerweise mit Ġunna verschmolzen, aber nicht, wenn Nūn und Yāʾ oder Wāw im selben Wort stehen: Dann wird das Nūn deutlich gesprochen, damit das Wort nicht zu etwas anderem wird (‚buyyān‘). Nur vier Wörter sind so (dunyā, ṣinwān, qinwān, bunyān). Die Regel heißt Iẓhār muṭlaq."],
    ar: ["في الكلمة المظللة نون ساكنة بعدها ياء في الكلمة نفسها. كيف تُقرأ؟", ["بالإظهار المطلق لأن الحرفين في كلمة واحدة", "بالإدغام بغنة كما في النون قبل الياء", "بالإخفاء", "بالقلب"], "النون قبل الياء والواو والنون والميم تُدغم عادةً بغنة، إلا إذا اجتمعت النون مع الياء أو الواو في كلمة واحدة فتُظهر خشية أن تلتبس الكلمة بغيرها (بيّان). وهذا في أربع كلمات فقط (الدنيا وصنوان وقنوان وبنيان) ويسمى الإظهار المطلق."] },

  { id: "xtj-021", s: "tajweed", g: 4, d: 6, t: ["idhhar", "disjointed-letters"], src: "al-Dānī, al-Taysīr; Ibn al-Jazarī, al-Nashr, bāb idghām al-ḥurūf al-muqaṭṭaʿa", v: "68:1", w: 1,
    en: ["The name of this letter ends in a nūn that is followed by the wāw of the oath. How does Ḥafṣ read it when continuing?", ["With iẓhār of the nūn (clear pronunciation)", "With idghām bi-ghunna into the wāw", "With ikhfāʾ", "With idghām bi-ghayr ghunna"], "In the riwāya of Ḥafṣ the nūn of the letter-name is pronounced clearly before the wāw (and likewise the nūn of sīn in 36:1). Some other readers merge the nūn into the wāw. The reason given is that the letters are read as separate, spelled-out names, and no merging is allowed in the spelling."],
    de: ["Der Name dieses Buchstabens endet auf ein Nūn, dem das Wāw des Schwurs folgt. Wie liest Ḥafṣ ihn beim Weiterlesen?", ["Mit Iẓhār des Nūn (deutliche Aussprache)", "Mit Idġām bi-ġunna in das Wāw", "Mit Iḫfāʾ", "Mit Idġām bi-ġayr ġunna"], "In der Riwāya von Ḥafṣ wird das Nūn des Buchstabennamens vor dem Wāw deutlich gesprochen (ebenso das Nūn von sīn in 36:1). Einige andere Leser verschmelzen das Nūn mit dem Wāw. Als Grund wird genannt, dass die Buchstaben als getrennte, buchstabierte Namen gelesen werden und beim Buchstabieren keine Verschmelzung erlaubt ist."],
    ar: ["اسم هذا الحرف ينتهي بنون يليها واو القسم. كيف يقرأ حفص عند الوصل؟", ["بإظهار النون", "بإدغامها بغنة في الواو", "بإخفائها", "بإدغامها بغير غنة"], "في رواية حفص تُظهر نون اسم الحرف قبل الواو (وكذلك نون اسم الحرف الثاني في يس 1)، بينما يدغمها في الواو بعض القراء. وسبب الإظهار أن الحروف المقطعة تُقرأ أسماءً مفصولة ولا يدخلها الإدغام في التهجي."] },

  { id: "xtj-022", s: "tajweed", g: 4, d: 6, t: ["idhhar", "disjointed-letters"], src: "al-Dānī, al-Taysīr; Ibn al-Jazarī, al-Nashr", v: "36:1", w: 1,
    en: ["How does Ḥafṣ read the nūn at the end of the name of the second letter in the highlighted word when the reading continues into the oath?", ["With iẓhār (the nūn is clearly pronounced)", "With idghām bi-ghunna", "With ikhfāʾ before the wāw", "With a lengthening of the nūn by six ḥarakāt"], "The nūn sākina is followed by a wāw, which would make an idghām by the general rule, but Ḥafṣ keeps it clear because the letters are spelled out separately. This reading is the same as in 68:1. Some other readers have an idghām here."],
    de: ["Wie liest Ḥafṣ das Nūn am Ende des Namens des zweiten Buchstabens im markierten Wort, wenn die Lesung in den Schwur übergeht?", ["Mit Iẓhār (das Nūn wird deutlich gesprochen)", "Mit Idġām bi-ġunna", "Mit Iḫfāʾ vor dem Wāw", "Mit einer Dehnung des Nūn um sechs Ḥarakāt"], "Das Nūn sākina wird von einem Wāw gefolgt, was nach der allgemeinen Regel ein Idġām ergäbe, aber Ḥafṣ hält es deutlich, weil die Buchstaben einzeln buchstabiert werden. Diese Lesung ist dieselbe wie in 68:1. Einige andere Leser haben hier ein Idġām."],
    ar: ["كيف يقرأ حفص نون اسم الحرف الثاني في الكلمة المظللة عند الوصل بالقسم؟", ["بالإظهار", "بالإدغام بغنة", "بالإخفاء عند الواو", "بمدّ النون ست حركات"], "النون الساكنة تليها واو فكان الأصل الإدغام، لكن حفصًا يظهرها لأن الحروف تُتهجّى منفصلة، وهي كقراءته في القلم 1، أما بعض القراء فيدغمون هنا."] },

  { id: "xtj-023", s: "tajweed", g: 4, d: 6, t: ["madd", "madd-ranking"], src: "Ibn al-Jazarī, al-Nashr, bāb al-madd wa-l-qaṣr; Ibn al-Jazarī, al-Tamhīd fī ʿIlm al-Tajwīd",
    en: ["Which order of the madd causes, from the strongest to the weakest, is the usual one in the books of tajwīd?", ["Lāzim, muttaṣil, ʿāriḍ lil-sukūn, munfaṣil, badal", "Muttaṣil, lāzim, munfaṣil, ʿāriḍ lil-sukūn, badal", "Badal, munfaṣil, ʿāriḍ lil-sukūn, muttaṣil, lāzim", "Munfaṣil, muttaṣil, lāzim, badal, ʿāriḍ lil-sukūn"], "Scholars say the strongest cause is a lasting sukūn (madd lāzim), then the hamza in the same word (muttaṣil), then a temporary sukūn at waqf (ʿāriḍ), then the hamza in the next word (munfaṣil), and the weakest the madd badal. When two causes meet in one letter, the stronger prevails; the ranking is used to settle conflicts of length."],
    de: ["Welche Reihenfolge der Madd-Ursachen, von der stärksten zur schwächsten, ist in den Tağwīd-Büchern üblich?", ["Lāzim, muttaṣil, ʿāriḍ lil-sukūn, munfaṣil, badal", "Muttaṣil, lāzim, munfaṣil, ʿāriḍ lil-sukūn, badal", "Badal, munfaṣil, ʿāriḍ lil-sukūn, muttaṣil, lāzim", "Munfaṣil, muttaṣil, lāzim, badal, ʿāriḍ lil-sukūn"], "Die Gelehrten sagen, die stärkste Ursache sei ein bleibendes Sukūn (Madd lāzim), dann das Hamza im selben Wort (muttaṣil), dann ein vorübergehendes Sukūn beim Waqf (ʿāriḍ), dann das Hamza im nächsten Wort (munfaṣil) und die schwächste das Madd badal. Treffen zwei Ursachen an einem Buchstaben zusammen, gewinnt die stärkere; die Rangfolge dient zur Klärung von Längenkonflikten."],
    ar: ["ما ترتيب أسباب المد من الأقوى إلى الأضعف في كتب التجويد؟", ["اللازم ثم المتصل ثم العارض للسكون ثم المنفصل ثم البدل", "المتصل ثم اللازم ثم المنفصل ثم العارض للسكون ثم البدل", "البدل ثم المنفصل ثم العارض للسكون ثم المتصل ثم اللازم", "المنفصل ثم المتصل ثم اللازم ثم البدل ثم العارض للسكون"], "قالوا أقوى الأسباب السكون الأصلي اللازم (المد اللازم) ثم الهمز في كلمة المد (المتصل) ثم السكون العارض للوقف ثم الهمز في كلمة أخرى (المنفصل) وأضعفها البدل. وإذا اجتمع سببان قوي وضعيف عُمل بالأقوى، ويُرجع إلى الترتيب عند تعارض المقادير."] },

  { id: "xtj-024", s: "tajweed", g: 4, d: 6, t: ["madd", "waqf"], src: "Ibn al-Jazarī, al-Nashr, bāb al-madd; al-Dānī, al-Taysīr", v: "2:22", w: 10,
    en: ["The highlighted word has a madd muttaṣil. Which lengths are permitted when the reader stops on it?", ["4, 5 or 6 ḥarakāt, but not 2", "2, 4 or 6 ḥarakāt", "Only 6 ḥarakāt", "Only 2 ḥarakāt"], "In waṣl Ḥafṣ reads muttaṣil with 4 or 5 ḥarakāt (and 6 in some ṭuruq). At waqf a second cause is added, the temporary sukūn, so the length may rise to 6, but it cannot fall below the length used in continuation, so 2 is not allowed. The three lengths 4, 5 and 6 are therefore the lengths allowed."],
    de: ["Das markierte Wort enthält ein Madd muttaṣil. Welche Längen sind erlaubt, wenn der Leser darauf stoppt?", ["4, 5 oder 6 Ḥarakāt, aber nicht 2", "2, 4 oder 6 Ḥarakāt", "Nur 6 Ḥarakāt", "Nur 2 Ḥarakāt"], "Beim Weiterlesen liest Ḥafṣ das Muttaṣil mit 4 oder 5 Ḥarakāt (in manchen Ṭuruq auch 6). Beim Waqf kommt eine zweite Ursache hinzu, das vorübergehende Sukūn, sodass die Länge auf 6 steigen kann, aber nicht unter die beim Weiterlesen gebrauchte Länge fallen darf, deshalb ist 2 nicht erlaubt. Erlaubt sind daher die Längen 4, 5 und 6."],
    ar: ["الكلمة المظللة فيها مد متصل. ما المقادير الجائزة عند الوقف عليها؟", ["أربع أو خمس أو ست حركات لا حركتان", "حركتان أو أربع أو ست", "ست حركات فقط", "حركتان فقط"], "يقرأ حفص المتصل في الوصل بأربع أو خمس حركات (وست في بعض الطرق)، وعند الوقف يضاف سبب ثانٍ هو السكون العارض فيجوز أن يبلغ ست حركات، لكنه لا ينقص عن مقداره في الوصل فلا يجوز القصر بحركتين، فالجائز أربع وخمس وست."] },

  { id: "xtj-025", s: "tajweed", g: 4, d: 6, t: ["madd", "madd-lin"], src: "Ibn al-Jazarī, al-Nashr, bāb madd al-līn; al-Dānī, al-Taysīr", v: "106:4", w: 7,
    en: ["If the reader stops on the highlighted word, which lengths are allowed for the madd līn before the final consonant?", ["2, 4 or 6 ḥarakāt", "Only 2 ḥarakāt", "Only 6 ḥarakāt", "Only 4 ḥarakāt"], "A sākin wāw or yāʾ after a fatḥa is a letter of līn, not a true madd letter. Before a temporary sukūn at waqf it may be lengthened with the same three lengths that apply to the madd ʿāriḍ lil-sukūn: 2, 4 or 6 ḥarakāt. It has no length in continuation."],
    de: ["Wenn der Leser auf dem markierten Wort stoppt, welche Längen sind für das Madd līn vor dem Endkonsonanten erlaubt?", ["2, 4 oder 6 Ḥarakāt", "Nur 2 Ḥarakāt", "Nur 6 Ḥarakāt", "Nur 4 Ḥarakāt"], "Ein Sākin-Wāw oder -Yāʾ nach Fatḥa ist ein Līn-Buchstabe, kein echter Madd-Buchstabe. Vor einem vorübergehenden Sukūn beim Waqf darf es mit denselben drei Längen gedehnt werden wie das Madd ʿāriḍ lil-sukūn: 2, 4 oder 6 Ḥarakāt. Beim Weiterlesen hat es keine Länge."],
    ar: ["إذا وقف القارئ على الكلمة المظللة فما المقادير الجائزة لمد اللين قبل الحرف الأخير؟", ["حركتان أو أربع أو ست", "حركتان فقط", "ست حركات فقط", "أربع حركات فقط"], "الواو أو الياء الساكنة بعد فتح حرف لين وليست حرف مد حقيقيًّا، وعند الوقف قبل سكون عارض يجوز مدّها بمقادير المد العارض للسكون: حركتان أو أربع أو ست، ولا مد فيها في الوصل."] },

  { id: "xtj-026", s: "tajweed", g: 4, d: 6, t: ["madd", "disjointed-letters"], src: "Ibn al-Jazarī, al-Nashr, bāb madd al-ḥurūf al-muqaṭṭaʿa; al-Shāṭibī, Ḥirz al-Amānī", v: "42:2", w: 1,
    en: ["What lengths does Ḥafṣ allow for the first letter of the highlighted group, whose name contains a līn letter followed by a lasting sukūn?", ["4 or 6 ḥarakāt", "Only 2 ḥarakāt", "Only 6 ḥarakāt", "2 or 4 ḥarakāt"], "The name of this letter has a yāʾ of līn followed by a lasting sukūn on the nūn, so it takes a madd lāzim of the līn type. In the riwāya of Ḥafṣ it may be read with 4 (tawassuṭ) or 6 (ṭūl) ḥarakāt, whereas the other letters with a madd lāzim take 6. Both lengths are established and equally correct."],
    de: ["Welche Längen erlaubt Ḥafṣ für den ersten Buchstaben der markierten Gruppe, dessen Name einen Līn-Buchstaben mit anschließendem bleibendem Sukūn enthält?", ["4 oder 6 Ḥarakāt", "Nur 2 Ḥarakāt", "Nur 6 Ḥarakāt", "2 oder 4 Ḥarakāt"], "Der Name dieses Buchstabens hat ein Līn-Yāʾ, gefolgt von einem bleibenden Sukūn auf dem Nūn, daher erhält er ein Madd lāzim vom Līn-Typ. In der Riwāya von Ḥafṣ darf er mit 4 (Tawassuṭ) oder 6 (Ṭūl) Ḥarakāt gelesen werden, während die anderen Buchstaben mit Madd lāzim 6 erhalten. Beide Längen sind belegt und gleich richtig."],
    ar: ["ما المقادير التي يجيزها حفص في الحرف الأول من المجموعة المظللة، وفي اسمه حرف لين بعده ساكن لازم؟", ["أربع أو ست حركات", "حركتان فقط", "ست حركات فقط", "حركتان أو أربع"], "في اسم هذا الحرف ياء لين يليها ساكن لازم فهو من المد اللازم من نوع اللين، وفي رواية حفص يجوز فيه التوسط (أربع حركات) والطول (ست حركات)، بينما سائر الحروف ذات المد اللازم ست حركات، والوجهان ثابتان صحيحان."] },

  { id: "xtj-027", s: "tajweed", g: 4, d: 6, t: ["madd", "disjointed-letters"], src: "Ibn al-Jazarī, al-Nashr, bāb madd al-ḥurūf al-muqaṭṭaʿa; Ibn al-Jazarī, al-Muqaddima", v: "20:1", w: 1,
    en: ["How many ḥarakāt does Ḥafṣ give to each of the two letters of the highlighted opening?", ["Two ḥarakāt each, a natural madd, since their names have no sākin letter after the madd", "Six ḥarakāt each, a madd lāzim", "Four ḥarakāt each", "Six for the first and two for the second"], "The five letters ḥ, y, ṭ, h and r (the group ‘ḥayy ṭuhur’) have names with a madd letter but no sukūn after it, so they are lengthened only two ḥarakāt (madd ṭabīʿī). The letters of the group ‘kam ʿasal naqṣ wa-qaraṣ’ have a madd lāzim of six, with ʿayn at four or six."],
    de: ["Wie viele Ḥarakāt gibt Ḥafṣ jedem der beiden Buchstaben des markierten Anfangs?", ["Je zwei Ḥarakāt, ein natürliches Madd, da ihre Namen nach dem Madd keinen Sākin-Buchstaben haben", "Je sechs Ḥarakāt, ein Madd lāzim", "Je vier Ḥarakāt", "Sechs für den ersten und zwei für den zweiten"], "Die fünf Buchstaben ḥ, y, ṭ, h und r (die Gruppe ‚ḥayy ṭuhur‘) haben Namen mit einem Madd-Buchstaben, aber ohne Sukūn danach, daher werden sie nur zwei Ḥarakāt gedehnt (Madd ṭabīʿī). Die Buchstaben der Gruppe ‚kam ʿasal naqṣ wa-qaraṣ‘ haben ein Madd lāzim von sechs, wobei ʿain vier oder sechs hat."],
    ar: ["كم حركة يمدّ حفص كل حرف من الحرفين في الفاتحة المظللة؟", ["حركتين لكل منهما مدًّا طبيعيًّا إذ ليس بعد مدّ اسمهما ساكن", "ست حركات لكل منهما مدًّا لازمًا", "أربع حركات لكل منهما", "ست للأول وحركتان للثاني"], "الحروف الخمسة «حي طهر» أسماؤها فيها حرف مد ولا ساكن بعده فتُمد حركتين مدًّا طبيعيًّا، أما حروف «كم عسل نقص وقرس» ففيها مد لازم ست حركات مع العين بأربع أو ست."] },

  { id: "xtj-028", s: "tajweed", g: 4, d: 6, t: ["madd", "disjointed-letters"], src: "Ibn al-Jazarī, al-Nashr, bāb madd al-ḥurūf al-muqaṭṭaʿa", v: "19:1", w: 1,
    en: ["In the five letters of the highlighted opening, which two letters are given exactly two ḥarakāt of madd by Ḥafṣ?", ["The second and the third: hāʾ and yāʾ (letters of ‘ḥayy ṭuhur’)", "The first and the fourth: kāf and ʿayn", "The first and the last: kāf and ṣād", "Only the middle letter, ʿayn"], "The five letters are kāf, hāʾ, yāʾ, ʿayn, ṣād. Kāf and ṣād have a madd lāzim of six; ʿayn has four or six; hāʾ and yāʾ have a natural madd of two ḥarakāt. The easiest way to learn this is the mnemonic of the groups of letters."],
    de: ["Welchen zwei der fünf Buchstaben des markierten Anfangs gibt Ḥafṣ genau zwei Ḥarakāt Madd?", ["Dem zweiten und dritten: Hāʾ und Yāʾ (Buchstaben von ‚ḥayy ṭuhur‘)", "Dem ersten und vierten: Kāf und ʿain", "Dem ersten und letzten: Kāf und Ṣād", "Nur dem mittleren Buchstaben, ʿain"], "Die fünf Buchstaben sind Kāf, Hāʾ, Yāʾ, ʿain, Ṣād. Kāf und Ṣād haben ein Madd lāzim von sechs; ʿain hat vier oder sechs; Hāʾ und Yāʾ haben ein natürliches Madd von zwei Ḥarakāt. Am einfachsten merkt man es mit der Merkformel der Buchstabengruppen."],
    ar: ["من الحروف الخمسة في الفاتحة المظللة، أي حرفين يمدهما حفص حركتين فقط؟", ["الثاني والثالث: الهاء والياء (من «حي طهر»)", "الأول والرابع: الكاف والعين", "الأول والأخير: الكاف والصاد", "الحرف الأوسط وحده: العين"], "الحروف: كاف وهاء ويا وعين وصاد. للكاف والصاد مد لازم ست حركات، وللعين أربع أو ست، وللهاء والياء مد طبيعي حركتان، ويسهل حفظه بجمل الحروف المعروفة."] },

  { id: "xtj-029", s: "tajweed", g: 4, d: 6, t: ["madd", "madd-lazim"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, bāb al-madd; al-Dānī, al-Taysīr", v: "1:7", w: 9,
    en: ["What is the name of the madd in the highlighted word and how many ḥarakāt does it have?", ["Madd lāzim kalimī muthaqqal, six ḥarakāt", "Madd muttaṣil, four or five ḥarakāt", "Madd ʿāriḍ lil-sukūn, two, four or six ḥarakāt", "Madd lāzim ḥarfī mukhaffaf, six ḥarakāt"], "The alif after the lām is followed by a lām with shadda, i.e. a lasting sukūn in the same word, so the madd is a lāzim kalimī; because the sukūn is a doubled letter, it is muthaqqal (heavy). It is six ḥarakāt by the agreement of the qurrāʾ. A lāzim ḥarfī belongs to the names of the letters at the openings of chapters."],
    de: ["Wie heißt das Madd im markierten Wort und wie viele Ḥarakāt hat es?", ["Madd lāzim kalimī muṯaqqal, sechs Ḥarakāt", "Madd muttaṣil, vier oder fünf Ḥarakāt", "Madd ʿāriḍ lil-sukūn, zwei, vier oder sechs Ḥarakāt", "Madd lāzim ḥarfī muḫaffaf, sechs Ḥarakāt"], "Auf das Alif folgt ein Lām mit Šadda, also ein bleibendes Sukūn im selben Wort; daher ist das Madd ein Lāzim kalimī, und weil das Sukūn ein verdoppelter Buchstabe ist, ist es muṯaqqal (schwer). Es hat sechs Ḥarakāt nach Übereinstimmung der Qurrāʾ. Ein Lāzim ḥarfī gehört zu den Buchstabennamen am Anfang von Suren."],
    ar: ["ما اسم المد في الكلمة المظللة وكم حركة هو؟", ["مد لازم كلمي مثقل ست حركات", "مد متصل أربع أو خمس حركات", "مد عارض للسكون حركتان أو أربع أو ست", "مد لازم حرفي مخفف ست حركات"], "بعد الألف لام مشددة أي سكون لازم في الكلمة نفسها فالمد لازم كلمي، ولأن الساكن حرف مدغم فهو مثقل، ومقداره ست حركات بإجماع القراء. أما اللازم الحرفي ففي أسماء الحروف في فواتح السور."] },

  { id: "xtj-030", s: "tajweed", g: 4, d: 6, t: ["madd", "madd-badal"], src: "Ibn al-Jazarī, al-Nashr, bāb al-madd; al-Shāṭibī, Ḥirz al-Amānī", v: "2:285", w: 1,
    en: ["The madd letter in the highlighted word follows a hamza in the same word. What is it and how long does Ḥafṣ make it?", ["Madd badal, two ḥarakāt", "Madd muttaṣil, four ḥarakāt", "Madd ʿāriḍ lil-sukūn, six ḥarakāt", "Madd līn, six ḥarakāt"], "When the hamza precedes the madd letter in the same word it is a madd badal (so called because the madd letter replaces a second hamza in the original form). Ḥafṣ reads it with two ḥarakāt only, while Warsh may read it with two, four or six. The madd muttaṣil requires the hamza to come after the madd letter."],
    de: ["Der Madd-Buchstabe im markierten Wort folgt im selben Wort auf ein Hamza. Was ist es und wie lang macht Ḥafṣ es?", ["Madd badal, zwei Ḥarakāt", "Madd muttaṣil, vier Ḥarakāt", "Madd ʿāriḍ lil-sukūn, sechs Ḥarakāt", "Madd līn, sechs Ḥarakāt"], "Geht das Hamza dem Madd-Buchstaben im selben Wort voran, ist es ein Madd badal (so genannt, weil der Madd-Buchstabe ein zweites Hamza der ursprünglichen Form ersetzt). Ḥafṣ liest es mit nur zwei Ḥarakāt, während Warš es mit zwei, vier oder sechs lesen kann. Das Madd muttaṣil verlangt, dass das Hamza nach dem Madd-Buchstaben steht."],
    ar: ["حرف المد في الكلمة المظللة يأتي بعد همزة في الكلمة نفسها. ما اسمه وكم يمدّه حفص؟", ["مد بدل حركتان", "مد متصل أربع حركات", "مد عارض للسكون ست حركات", "مد لين ست حركات"], "إذا تقدمت الهمزة على حرف المد في الكلمة سُمي مد بدل لأن حرف المد بدل من همزة ثانية في الأصل، ويمدّه حفص حركتين فقط وقد يمده ورش حركتين أو أربعًا أو ستًّا، أما المتصل فتأتي فيه الهمزة بعد حرف المد."] },

  { id: "xtj-031", s: "tajweed", g: 4, d: 7, t: ["lam-jalala", "iltiqa-sakinayn"], src: "Ibn al-Jazarī, al-Nashr, bāb al-lāmāt; Ibn al-Jazarī, al-Muqaddima al-Jazariyya", v: "112:2", w: 1,
    en: ["When the reader continues from the end of 112:1 into 112:2, how is the lām of the highlighted name of God pronounced?", ["Light (tarqīq), because the preceding tanwīn is resolved with a kasra", "Heavy (tafkhīm), because the preceding word ends in ḍamma", "Heavy, because the lām follows a sākin letter", "Light only if the reader makes a sakta"], "The tanwīn of the previous word meets the hamzat waṣl of the next, and the two sākin letters are resolved by a kasra on the tanwīn. The kasra, even if temporary, makes the lām of Allāh light. The lām is heavy only after a fatḥa or ḍamma."],
    de: ["Wenn der Leser vom Ende von 112:1 in 112:2 weiterliest, wie wird das Lām des markierten Gottesnamens ausgesprochen?", ["Leicht (Tarqīq), weil das vorangehende Tanwīn mit einer Kasra aufgelöst wird", "Schwer (Tafḫīm), weil das vorige Wort auf Ḍamma endet", "Schwer, weil das Lām auf einen Sākin-Buchstaben folgt", "Leicht nur, wenn der Leser eine Sakta macht"], "Das Tanwīn des vorigen Wortes trifft auf das Hamzat al-waṣl des nächsten, und die beiden Sākin-Buchstaben werden durch eine Kasra auf dem Tanwīn aufgelöst. Die Kasra, auch wenn sie vorübergehend ist, macht das Lām von Allāh leicht. Das Lām ist nur nach Fatḥa oder Ḍamma schwer."],
    ar: ["إذا وصل القارئ آخر الآية الأولى بالثانية فكيف يُنطق اللام في لفظ الجلالة المظلل؟", ["مرققة لأن التنوين قبلها يُكسر للتخلص من التقاء الساكنين", "مفخّمة لأن الكلمة السابقة تنتهي بضمة", "مفخّمة لأن اللام تلي حرفًا ساكنًا", "مرققة إذا سكت القارئ فقط"], "يلتقي تنوين الكلمة السابقة بهمزة الوصل في الكلمة التالية فيُكسر التنوين للتخلص من التقاء الساكنين، وهذه الكسرة ولو كانت عارضة ترقق لام لفظ الجلالة، فلا تُفخّم إلا بعد فتح أو ضم."] },

  { id: "xtj-032", s: "tajweed", g: 4, d: 6, t: ["iltiqa-sakinayn", "tanwin"], src: "Ibn al-Jazarī, al-Nashr, bāb iltiqāʾ al-sākinayn; Ibn al-Jazarī, al-Tamhīd", v: "112:1", w: 4,
    en: ["The highlighted word ends in tanwīn, and the next verse begins with a hamzat waṣl. What happens to the tanwīn when the reader continues?", ["The tanwīn is resolved with a kasra on the nūn", "The tanwīn is dropped completely", "The tanwīn takes fatḥa", "The tanwīn is merged into the following letter"], "A sākin nūn of tanwīn meets the sākin lām of the article (after the hamza of waṣl is lost in continuation). The general rule is that the first sākin is given kasra to remove the cluster, so the tanwīn nūn is read with kasra. Other letters such as mīm al-jamʿ take ḍamma and min before al takes fatḥa."],
    de: ["Das markierte Wort endet auf Tanwīn, und der nächste Vers beginnt mit einem Hamzat al-waṣl. Was geschieht mit dem Tanwīn beim Weiterlesen?", ["Das Tanwīn wird durch eine Kasra auf dem Nūn aufgelöst", "Das Tanwīn fällt ganz weg", "Das Tanwīn erhält Fatḥa", "Das Tanwīn verschmilzt mit dem folgenden Buchstaben"], "Ein Sākin-Nūn des Tanwīn trifft auf das Sākin-Lām des Artikels (nachdem das Hamza des Waṣl beim Weiterlesen entfallen ist). Die allgemeine Regel lautet, dass der erste Sākin eine Kasra erhält, um die Häufung zu beseitigen; also wird das Tanwīn-Nūn mit Kasra gelesen. Andere Buchstaben wie das Mīm al-ǧamʿ erhalten Ḍamma und min vor al erhält Fatḥa."],
    ar: ["الكلمة المظللة تنتهي بتنوين والآية بعدها تبدأ بهمزة وصل. ماذا يحدث للتنوين عند الوصل؟", ["يُكسر التنوين للتخلص من التقاء الساكنين", "يسقط التنوين تمامًا", "يُفتح التنوين", "يدغم التنوين في الحرف بعده"], "تلتقي نون التنوين الساكنة بلام التعريف الساكنة بعد سقوط همزة الوصل، والأصل التخلص بكسر الأول فتُكسر نون التنوين. أما ميم الجمع فتضم وحرف الجر قبل أداة التعريف يُفتح."] },

  { id: "xtj-033", s: "tajweed", g: 4, d: 6, t: ["iltiqa-sakinayn", "hamzat-wasl"], src: "Ibn al-Jazarī, al-Nashr, bāb iltiqāʾ al-sākinayn; Makkī ibn Abī Ṭālib, al-Ri'āya", v: "114:6", w: 1,
    en: ["Why does the nūn of the highlighted preposition take fatḥa before the article, whereas it takes kasra before most other words with hamzat waṣl?", ["Because three kasras in succession would be heavy, so the fatḥa is preferred before the article", "Because the article is always preceded by fatḥa", "Because the preposition is a noun", "Because it follows a vowel letter"], "When min meets al, the nūn is sākin before the sākin lām, and the usual remedy would be a kasra. But the pronunciation would then have repeated kasras in ‘mini l-jinna’, so the Arabs and the qurrāʾ chose fatḥa for lightness. Before other words with hamzat waṣl, such as ibn, the kasra is kept."],
    de: ["Warum erhält das Nūn der markierten Präposition vor dem Artikel Fatḥa, während es vor den meisten anderen Wörtern mit Hamzat al-waṣl Kasra erhält?", ["Weil drei Kasra hintereinander schwer wären, daher wird vor dem Artikel die Fatḥa bevorzugt", "Weil dem Artikel immer eine Fatḥa vorangeht", "Weil die Präposition ein Nomen ist", "Weil sie auf einen Vokalbuchstaben folgt"], "Trifft min auf al, ist das Nūn sākin vor dem Sākin-Lām, und das übliche Mittel wäre eine Kasra. Dann gäbe es aber wiederholte Kasra in ‚mini l-ǧinna‘, daher wählten die Araber und die Qurrāʾ die Fatḥa zur Erleichterung. Vor anderen Wörtern mit Hamzat al-waṣl wie ibn bleibt die Kasra."],
    ar: ["لماذا تُفتح نون حرف الجر المظلل قبل «أل» بينما تُكسر قبل أكثر الكلمات ذات همزة الوصل؟", ["لأن توالي كسرات ثلاث ثقيل فاختير الفتح تخفيفًا قبل أل", "لأن «أل» يسبقها فتح دائمًا", "لأن حرف الجر اسم", "لأنه يلي حرف لين"], "إذا لقي حرف الجر هذا لام التعريف كانت النون ساكنة قبل لام ساكنة والأصل الكسر، لكن توالي الكسرات يثقل النطق فاختار العرب والقراء الفتح تخفيفًا، أما قبل غيرها من همزات الوصل كابن فيبقى الكسر."] },

  { id: "xtj-034", s: "tajweed", g: 4, d: 6, t: ["iltiqa-sakinayn", "mim-jam"], src: "Ibn al-Jazarī, al-Nashr, bāb mīm al-jamʿ; al-Dānī, al-Taysīr", v: "2:183", w: 5,
    en: ["How does Ḥafṣ read the mīm of the plural before the sākin lām of the article, as in the highlighted word?", ["With ḍamma on the mīm (in continuation)", "With kasra on the mīm", "With fatḥa on the mīm", "With sukūn, merging into the lām"], "The mīm al-jamʿ was originally ḍamma plus a madd wāw (as in ‘ʿalaykumū’). When a sākin follows, the ḍamma is restored in place of the wāw. Some other readers give the mīm a kasra when it follows a kasra or yāʾ."],
    de: ["Wie liest Ḥafṣ das Mīm des Plurals vor dem Sākin-Lām des Artikels, wie im markierten Wort?", ["Mit Ḍamma auf dem Mīm (beim Weiterlesen)", "Mit Kasra auf dem Mīm", "Mit Fatḥa auf dem Mīm", "Mit Sukūn, verschmolzen mit dem Lām"], "Das Mīm al-ǧamʿ war ursprünglich Ḍamma plus ein Madd-Wāw (wie in ‚ʿalaikumū‘). Folgt ein Sākin, wird statt des Wāw die Ḍamma wiederhergestellt. Manche andere Leser geben dem Mīm eine Kasra, wenn es auf Kasra oder Yāʾ folgt."],
    ar: ["كيف يقرأ حفص ميم الجمع قبل لام التعريف الساكنة كما في الكلمة المظللة؟", ["بضم الميم عند الوصل", "بكسر الميم", "بفتح الميم", "بتسكين الميم وإدغامها في اللام"], "أصل ميم الجمع الضم مع واو مد (كعليكمو)، فإذا جاء بعدها ساكن رُدّت الضمة وسقطت الواو. وبعض القراء يكسر الميم إذا سبقتها كسرة أو ياء."] },

  { id: "xtj-035", s: "tajweed", g: 4, d: 6, t: ["iltiqa-sakinayn", "wawu-jama"], src: "Ibn al-Jazarī, al-Nashr, bāb iltiqāʾ al-sākinayn", v: "103:3", w: 4,
    en: ["What happens to the wāw of the group at the end of the highlighted verb when the reader continues into the next word, which starts with the article?", ["It is dropped in pronunciation, leaving ḍamma on the preceding letter", "It is lengthened by six ḥarakāt", "It is read with kasra", "It is changed into a hamza"], "The wāw of the plural is a sākin madd letter and meets the sākin lām of the article after the hamza of waṣl has been dropped. A sākin madd letter is lost in speech when followed by a sākin (ḥadhf li-iltiqāʾ al-sākinayn), so the verb ends with the ḍamma only. In writing it stays, together with the alif that follows."],
    de: ["Was geschieht mit dem Wāw der Gruppe am Ende des markierten Verbs, wenn der Leser ins nächste Wort mit dem Artikel weiterliest?", ["Es entfällt in der Aussprache und lässt eine Ḍamma auf dem vorigen Buchstaben zurück", "Es wird um sechs Ḥarakāt gedehnt", "Es wird mit Kasra gelesen", "Es wird in ein Hamza verwandelt"], "Das Wāw des Plurals ist ein Sākin-Madd-Buchstabe und trifft auf das Sākin-Lām des Artikels, nachdem das Hamza des Waṣl weggefallen ist. Ein Sākin-Madd-Buchstabe geht beim Sprechen verloren, wenn ein Sākin folgt (ḥaḏf li-ltiqāʾ as-sākinain), sodass das Verb nur mit der Ḍamma endet. Geschrieben bleibt es samt dem folgenden Alif."],
    ar: ["ماذا يحدث لواو الجماعة في آخر الفعل المظلل إذا وصل القارئ بالكلمة التالية التي تبدأ بأل؟", ["تُحذف نطقًا وتبقى الضمة على الحرف قبلها", "تُمدّ ست حركات", "تُقرأ بالكسر", "تُقلب همزة"], "واو الجماعة حرف مد ساكن يلقي لام التعريف الساكنة بعد سقوط همزة الوصل، وحرف المد الساكن يُحذف نطقًا عند التقائه بساكن فيبقى الفعل منتهيًا بالضمة، وتبقى الواو والألف مكتوبتين."] },

  { id: "xtj-036", s: "tajweed", g: 4, d: 7, t: ["ra-rules", "ibtida"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, bāb al-rāʾāt; Ibn al-Jazarī, al-Nashr", v: "89:28", w: 1,
    en: ["If a reader begins at the highlighted word, how is the rāʾ sākina pronounced, and why?", ["Heavy (tafkhīm), because the kasra before it is temporary, belonging to the hamzat waṣl", "Light (tarqīq), because it follows a kasra", "Light, because it is followed by the letter jīm", "Heavy, because it is followed by a letter of istiʿlāʾ"], "A rāʾ sākina after a kasra is normally light, provided that kasra belongs to the word itself and no letter of istiʿlāʾ follows. Here the kasra belongs to the added hamzat waṣl, not to the root; such a ʿāriḍ kasra does not count. The rāʾ is therefore heavy, as in other imperatives of this pattern."],
    de: ["Wenn ein Leser beim markierten Wort beginnt, wie wird das Rāʾ sākina ausgesprochen, und warum?", ["Schwer (Tafḫīm), weil die Kasra davor vorübergehend ist und zum Hamzat al-waṣl gehört", "Leicht (Tarqīq), weil es auf eine Kasra folgt", "Leicht, weil der Buchstabe Ǧīm folgt", "Schwer, weil ein Istiʿlāʾ-Buchstabe folgt"], "Ein Rāʾ sākina nach Kasra ist normalerweise leicht, sofern die Kasra zum Wort selbst gehört und kein Istiʿlāʾ-Buchstabe folgt. Hier gehört die Kasra zum hinzugefügten Hamzat al-waṣl, nicht zur Wurzel; eine solche ʿāriḍ-Kasra zählt nicht. Das Rāʾ ist daher schwer, wie in anderen Imperativen dieses Musters."],
    ar: ["إذا ابتدأ القارئ بالكلمة المظللة فكيف تُنطق الراء الساكنة ولماذا؟", ["مفخّمة لأن الكسرة قبلها عارضة وهي كسرة همزة الوصل", "مرققة لأنها بعد كسرة", "مرققة لأن بعدها حرف الجيم", "مفخّمة لأن بعدها حرف استعلاء"], "الراء الساكنة بعد الكسرة ترقق إذا كانت الكسرة من أصل الكلمة ولم يأت بعدها حرف استعلاء. وهنا الكسرة كسرة همزة الوصل وليست أصلية فلا يُعتد بها، وتُفخّم الراء كما في نظائرها من الأوامر."] },

  { id: "xtj-037", s: "tajweed", g: 4, d: 7, t: ["idgham", "idgham-naqis"], src: "Ibn al-Jazarī, al-Nashr, bāb al-idghām; Ibn al-Jazarī, al-Tamhīd", v: "77:20", w: 2,
    en: ["What is the nature of the idghām in the highlighted word, where qāf meets kāf?", ["An idghām ṣaghīr nāqiṣ of mutaqāribayn: the qāf is merged into the kāf but keeps its elevation (istiʿlāʾ)", "A complete idghām kāmil of mutajānisayn", "An iẓhār because qāf and kāf are distant letters", "An ikhfāʾ without ghunna"], "Qāf and kāf are close in their articulation points (mutaqāribān) and not identical. Ḥafṣ merges the qāf into the kāf, but because qāf has istiʿlāʾ, a strong quality that the kāf lacks, the merge is incomplete and the sound of the qāf's height remains. The mark in the muṣḥaf is the shadda on the kāf."],
    de: ["Welcher Art ist das Idġām im markierten Wort, in dem Qāf auf Kāf trifft?", ["Ein Idġām ṣaġīr nāqiṣ von Mutaqāribain: Das Qāf geht im Kāf auf, behält aber seine Erhebung (Istiʿlāʾ)", "Ein vollständiges Idġām kāmil von Mutaǧānisain", "Ein Iẓhār, weil Qāf und Kāf entfernte Buchstaben sind", "Ein Iḫfāʾ ohne Ġunna"], "Qāf und Kāf liegen in ihren Artikulationsorten nahe beieinander (mutaqāribān), sind aber nicht gleich. Ḥafṣ lässt das Qāf im Kāf aufgehen, doch da das Qāf Istiʿlāʾ hat, eine starke Eigenschaft, die dem Kāf fehlt, ist die Verschmelzung unvollständig, und der Klang der Höhe des Qāf bleibt. Das Zeichen im Muṣḥaf ist die Šadda auf dem Kāf."],
    ar: ["ما طبيعة الإدغام في الكلمة المظللة التي تلتقي فيها القاف بالكاف؟", ["إدغام صغير ناقص في المتقاربين تُدغم القاف في الكاف مع بقاء صفة الاستعلاء", "إدغام كامل في المتجانسين", "إظهار لأن القاف والكاف متباعدان", "إخفاء بلا غنة"], "القاف والكاف متقاربان مخرجًا لا متماثلان، فيدغم حفص القاف في الكاف لكن للقاف استعلاء قوي ليس في الكاف فيكون الإدغام ناقصًا ويبقى أثر علو القاف، وعلامته في المصحف الشدة على الكاف."] },

  { id: "xtj-038", s: "tajweed", g: 4, d: 6, t: ["ibtida", "hamzat-wasl"], src: "Ibn al-Jazarī, al-Nashr, bāb al-ibtidāʾ; al-Dānī, al-Muktafā fī al-Waqf wa-l-Ibtidāʾ", v: "12:9", w: 1,
    en: ["With which vowel does a reader begin the highlighted verb, which starts with a hamzat waṣl?", ["With ḍamma, because the third letter has an original ḍamma", "With kasra, as for all hamzat waṣl in verbs", "With fatḥa, as for the article", "With sukūn"], "In the beginning of a verb with a hamzat waṣl the vowel follows the third letter: if its vowel is ḍamma (original), start with ḍamma; if fatḥa or kasra, start with kasra. Here the third letter has ḍamma, so one starts with ḍamma. The beginning with a ḍamma is not allowed when the ḍamma is temporary."],
    de: ["Mit welchem Vokal beginnt ein Leser das markierte Verb, das mit einem Hamzat al-waṣl anfängt?", ["Mit Ḍamma, weil der dritte Buchstabe eine ursprüngliche Ḍamma hat", "Mit Kasra, wie bei allen Hamzat al-waṣl in Verben", "Mit Fatḥa, wie beim Artikel", "Mit Sukūn"], "Beim Beginn eines Verbs mit Hamzat al-waṣl richtet sich der Vokal nach dem dritten Buchstaben: Hat er Ḍamma (ursprünglich), beginnt man mit Ḍamma; bei Fatḥa oder Kasra beginnt man mit Kasra. Hier hat der dritte Buchstabe Ḍamma, also beginnt man mit Ḍamma. Der Beginn mit Ḍamma ist nicht erlaubt, wenn die Ḍamma vorübergehend ist."],
    ar: ["بأي حركة يبتدئ القارئ الفعل المظلل الذي يبدأ بهمزة وصل؟", ["بالضم لأن الحرف الثالث مضموم ضمًّا أصليًّا", "بالكسر كما في سائر همزات الوصل في الأفعال", "بالفتح كما في أل", "بالسكون"], "يُبتدأ بهمزة وصل الفعل بحسب حركة الحرف الثالث: إذا كان مضمومًا ضمًّا أصليًّا ضُمّت الهمزة وإلا كُسرت. وهنا الثالث مضموم فيبدأ بالضم، ولا يُبتدأ بالضم إذا كانت ضمة الثالث عارضة."] },

  { id: "xtj-039", s: "tajweed", g: 4, d: 6, t: ["ibtida", "hamzat-wasl"], src: "Ibn al-Jazarī, al-Nashr, bāb al-ibtidāʾ; al-Dānī, al-Muktafā", v: "2:60", w: 6,
    en: ["With which vowel does a reader begin the highlighted imperative, which starts with a hamzat waṣl?", ["With kasra, because the third letter has kasra", "With ḍamma, because the third letter has ḍamma", "With fatḥa", "With sukūn"], "The vowel of the beginning is decided by the third letter of the verb. In this imperative the third letter, the rāʾ, has kasra, so the hamza is begun with kasra. Compare the verb of 12:9, where the third letter has ḍamma and the reader begins with ḍamma."],
    de: ["Mit welchem Vokal beginnt ein Leser den markierten Imperativ, der mit Hamzat al-waṣl anfängt?", ["Mit Kasra, weil der dritte Buchstabe Kasra hat", "Mit Ḍamma, weil der dritte Buchstabe Ḍamma hat", "Mit Fatḥa", "Mit Sukūn"], "Der Vokal des Beginns richtet sich nach dem dritten Buchstaben des Verbs. In diesem Imperativ hat der dritte Buchstabe, das Rāʾ, Kasra, also beginnt man das Hamza mit Kasra. Man vergleiche das Verb in 12:9, wo der dritte Buchstabe Ḍamma hat und man mit Ḍamma beginnt."],
    ar: ["بأي حركة يبتدئ القارئ فعل الأمر المظلل الذي يبدأ بهمزة وصل؟", ["بالكسر لأن الحرف الثالث مكسور", "بالضم لأن الحرف الثالث مضموم", "بالفتح", "بالسكون"], "تحدد حركة الحرف الثالث حركة الابتداء، وفي هذا الأمر الثالث وهو الراء مكسور فتُكسر الهمزة. وقارن فعل يوسف 9 حيث الثالث مضموم فيبدأ بالضم."] },

  { id: "xtj-040", s: "tajweed", g: 4, d: 7, t: ["ibtida", "hamzat-wasl"], src: "Ibn al-Jazarī, al-Nashr, bāb al-ibtidāʾ; Ibn al-Jazarī, al-Muqaddima", v: "38:6", w: 5,
    en: ["With which vowel does a reader begin the highlighted imperative of the group, which starts with a hamzat waṣl?", ["With ḍamma, because the original vowel of the third letter is ḍamma", "With kasra, because the second letter has a kasra", "With fatḥa, because the second letter is sākin", "With sukūn"], "The imperative is formed from the imperfect with ḍamma on its middle consonant, hence the third letter has an original ḍamma. The beginner uses ḍamma on the hamza to match, as in 12:9. The nūn and mīm are letters of the root and here the reader counts letters of the verb from the hamza."],
    de: ["Mit welchem Vokal beginnt ein Leser den markierten Imperativ der Gruppe, der mit Hamzat al-waṣl anfängt?", ["Mit Ḍamma, weil der ursprüngliche Vokal des dritten Buchstabens Ḍamma ist", "Mit Kasra, weil der zweite Buchstabe Kasra hat", "Mit Fatḥa, weil der zweite Buchstabe Sākin ist", "Mit Sukūn"], "Der Imperativ wird aus dem Imperfekt mit Ḍamma auf dem mittleren Konsonanten gebildet, daher hat der dritte Buchstabe eine ursprüngliche Ḍamma. Der Beginnende setzt Ḍamma auf das Hamza, damit es passt, wie in 12:9. Nūn und Mīm sind Wurzelbuchstaben, und der Leser zählt die Buchstaben des Verbs vom Hamza an."],
    ar: ["بأي حركة يبتدئ القارئ فعل الأمر المظلل الذي يبدأ بهمزة وصل؟", ["بالضم لأن الحرف الثالث مضموم في الأصل", "بالكسر لأن الحرف الثاني مكسور", "بالفتح لأن الحرف الثاني ساكن", "بالسكون"], "يُشتق الأمر من المضارع المضموم العين فيكون ثالث حروفه مضمومًا في الأصل فتُضم الهمزة عند الابتداء كما في يوسف 9، ويُعدّ الحرف الثالث بدءًا من الهمزة."] },
];
